@CrossOrigin
@RestController
@RequestMapping("/PrivacyNoticeQuery")
public class PrivacyNoticeQueryRestController extends BaseSpringRestController {
	
	public PrivacyNoticeQueryRestController( PrivacyNoticeService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a PrivacyNotice using a UUID
     * @param		UUID privacyNoticeId
     * @return		PrivacyNotice
     */    
    @GetMapping("/load")
    public PrivacyNotice load( @RequestParam(required=true) UUID privacyNoticeId ) {
    	PrivacyNotice entity = null;

    	try {  
    		entity = service.getPrivacyNotice( new PrivacyNoticeFetchOneSummary( privacyNoticeId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load PrivacyNotice using Id " + privacyNoticeId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all PrivacyNotice business objects
     * @return		Set<PrivacyNotice>
     */
    @GetMapping("/")
    public List<PrivacyNotice> loadAll() {                
    	List<PrivacyNotice> privacyNoticeList = null;
        
    	try {
            // load the PrivacyNotice
            privacyNoticeList = service.getAllPrivacyNotice();
            
            if ( privacyNoticeList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all PrivacyNotices" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all PrivacyNotices ", exc );
        	return null;
        }

        return privacyNoticeList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected PrivacyNotice privacyNotice = null;
    protected PrivacyNoticeService service = null;
    private static final Logger LOGGER = Logger.getLogger(PrivacyNoticeQueryRestController.class.getName());
    
}
